import{_ as r,o as i,c as l,X as e}from"./chunks/framework.6bc268d3.js";const u=JSON.parse('{"title":"Wireframe(线框图)","description":"","frontmatter":{},"headers":[],"relativePath":"markdown/pd_manager_knowledge/Wireframe.md","filePath":"markdown/pd_manager_knowledge/Wireframe.md","lastUpdated":null}'),o={name:"markdown/pd_manager_knowledge/Wireframe.md"},a=e('<h1 id="wireframe-线框图" tabindex="-1">Wireframe(线框图) <a class="header-anchor" href="#wireframe-线框图" aria-label="Permalink to &quot;Wireframe(线框图)&quot;">​</a></h1><p><strong>Wireframe</strong> 中文通常翻译为 <strong>线框图</strong>，是用户界面（UI）设计中一种重要的工具，主要用来展示产品页面的结构和布局。它以简单的线条、框架和占位符的形式勾勒出页面或功能的初步设计蓝图，是产品设计过程中的早期阶段。</p><h2 id="wireframe-的核心特点" tabindex="-1"><strong>Wireframe 的核心特点</strong> <a class="header-anchor" href="#wireframe-的核心特点" aria-label="Permalink to &quot;**Wireframe 的核心特点**&quot;">​</a></h2><ol><li><p><strong>简洁直观</strong>：<br> 不注重美观和细节，只关注页面的基本框架和信息布局。</p></li><li><p><strong>功能导向</strong>：<br> 专注于用户交互流程、功能模块和信息层级的呈现。</p></li><li><p><strong>低保真</strong>：<br> 使用简单的图形元素（如矩形、圆形、文本占位符等）表示功能和内容。</p></li><li><p><strong>可快速迭代</strong>：<br> 设计灵活，修改成本低，便于与团队成员和利益相关者协作讨论。</p></li></ol><h2 id="wireframe-的作用" tabindex="-1"><strong>Wireframe 的作用</strong> <a class="header-anchor" href="#wireframe-的作用" aria-label="Permalink to &quot;**Wireframe 的作用**&quot;">​</a></h2><ol><li><p><strong>定义产品结构</strong>：<br> 明确页面的主要功能模块及其布局方式。</p></li><li><p><strong>优化用户体验</strong>：<br> 在早期阶段评估用户交互路径和信息架构，发现潜在问题。</p></li><li><p><strong>沟通与协作工具</strong>：<br> 为产品经理、设计师、开发团队和客户提供直观的参考，确保对需求的一致理解。</p></li><li><p><strong>降低开发成本</strong>：<br> 在实际开发之前，验证设计思路并尽早发现问题，减少后期修改成本。</p></li></ol><h2 id="wireframe-的组成部分" tabindex="-1"><strong>Wireframe 的组成部分</strong> <a class="header-anchor" href="#wireframe-的组成部分" aria-label="Permalink to &quot;**Wireframe 的组成部分**&quot;">​</a></h2><ol><li><p><strong>页面结构</strong>：<br> 使用框架表示主要区域的划分，如头部、导航栏、内容区和页脚。</p></li><li><p><strong>功能模块</strong>：<br> 标记按钮、表单、搜索框等核心交互元素的位置和功能。</p></li><li><p><strong>占位符内容</strong>：<br> 用灰色框或虚线表示图片、文本等内容的预留位置。</p></li><li><p><strong>注释</strong>：<br> 在图中添加简单说明，帮助开发者或利益相关方理解设计意图。</p></li></ol><h2 id="wireframe-的分类" tabindex="-1"><strong>Wireframe 的分类</strong> <a class="header-anchor" href="#wireframe-的分类" aria-label="Permalink to &quot;**Wireframe 的分类**&quot;">​</a></h2><ol><li><p><strong>低保真线框图（Low-Fidelity Wireframe）</strong>：</p><ul><li>使用基本图形元素和占位符，不包含任何视觉设计细节。</li><li>目的：快速定义功能和布局，便于头脑风暴和初期讨论。</li></ul></li><li><p><strong>中保真线框图（Mid-Fidelity Wireframe）</strong>：</p><ul><li>增加了一些交互细节和文本，呈现更接近实际的用户流程。</li><li>目的：在低保真的基础上细化功能和用户路径。</li></ul></li><li><p><strong>高保真线框图（High-Fidelity Wireframe）</strong>：</p><ul><li>包含更丰富的视觉元素和交互效果，接近最终设计稿。</li><li>目的：用于展示最终功能和布局方案，但仍未加入完整的设计细节。</li></ul></li></ol><h2 id="wireframe-的设计工具" tabindex="-1"><strong>Wireframe 的设计工具</strong> <a class="header-anchor" href="#wireframe-的设计工具" aria-label="Permalink to &quot;**Wireframe 的设计工具**&quot;">​</a></h2><ol><li><p><strong>专业设计工具</strong>：</p><ul><li><strong>Figma</strong>：在线协作，适合团队使用。</li><li><strong>Sketch</strong>：专注于 UI 设计，功能丰富。</li><li><strong>Adobe XD</strong>：适合交互原型设计。</li><li><strong>Axure</strong>：支持高保真线框和复杂交互。</li></ul></li><li><p><strong>快速绘制工具</strong>：</p><ul><li><strong>Balsamiq</strong>：适合低保真线框图设计，操作简单。</li><li><strong>Whimsical</strong>：在线绘制线框图，轻量化工具。</li></ul></li><li><p><strong>自由绘制工具</strong>：</p><ul><li><strong>白板或纸笔</strong>：适合快速构思和即时修改。</li></ul></li></ol><h2 id="wireframe-的应用场景" tabindex="-1"><strong>Wireframe 的应用场景</strong> <a class="header-anchor" href="#wireframe-的应用场景" aria-label="Permalink to &quot;**Wireframe 的应用场景**&quot;">​</a></h2><ol><li><p><strong>产品需求阶段</strong>：<br> 产品经理用线框图表达功能需求和用户路径，便于团队讨论。</p></li><li><p><strong>设计阶段</strong>：<br> 设计师用线框图确定界面布局和交互流程，再进一步完善为高保真设计稿。</p></li><li><p><strong>开发阶段</strong>：<br> 开发团队根据线框图理解页面功能模块和内容结构。</p></li><li><p><strong>测试和迭代阶段</strong>：<br> 用户可以通过线框图快速体验核心功能，给出反馈。</p></li></ol><h2 id="示例-电商平台的线框图" tabindex="-1"><strong>示例：电商平台的线框图</strong> <a class="header-anchor" href="#示例-电商平台的线框图" aria-label="Permalink to &quot;**示例：电商平台的线框图**&quot;">​</a></h2><ol><li><p><strong>首页</strong>：</p><ul><li>导航栏：分类、搜索框、购物车按钮。</li><li>轮播图：促销活动或推荐商品。</li><li>商品列表：按分类展示热门商品。</li></ul></li><li><p><strong>商品详情页</strong>：</p><ul><li>图片区域：商品图片占位符。</li><li>商品信息：名称、价格、描述的简要位置框架。</li><li>购买按钮：放置在明显位置。</li></ul></li><li><p><strong>购物车页</strong>：</p><ul><li>列表区：商品名称、数量、价格的占位框。</li><li>结算按钮：放置在页面底部。</li></ul></li></ol><h2 id="wireframe-的注意事项" tabindex="-1"><strong>Wireframe 的注意事项</strong> <a class="header-anchor" href="#wireframe-的注意事项" aria-label="Permalink to &quot;**Wireframe 的注意事项**&quot;">​</a></h2><ol><li><p><strong>关注信息层级</strong>：<br> 确保重要信息和功能突出，次要信息合理分布。</p></li><li><p><strong>避免过早关注细节</strong>：<br> 线框图阶段不需要精细化设计，避免浪费时间。</p></li><li><p><strong>保证简洁明了</strong>：<br> 界面元素不宜过多，以免增加复杂度和理解难度。</p></li><li><p><strong>及时沟通和反馈</strong>：<br> 将线框图与团队分享，尽早收集意见并优化设计。</p></li></ol><p>总结来说，Wireframe 是产品设计和开发过程中的基础工具，它通过简单的页面布局图帮助团队快速定义产品结构、明确用户交互路径，并在早期验证设计思路，为后续的高保真设计和开发打下坚实的基础。</p>',19),t=[a];function n(s,g,p,m,f,d){return i(),l("div",null,t)}const b=r(o,[["render",n]]);export{u as __pageData,b as default};
